import test from 'node:test';import assert from 'node:assert/strict';
import {freshState,crewOrder} from '../engine.js';import {createBundle,decodeBundle} from '../save-bundle.js';
const id='11111111-1111-4111-8111-111111111111';
const fixture=()=>{const state=freshState(93);crewOrder(state,'harin','hire');return {state,images:[{key:'93:person:harin',active:id,versions:[{id,data:'data:image/png;base64,iVBORw0KGgo=',prompt:'portrait',model:'test',time:123}]}],settings:{drafts:{'novelai:person:harin':'style and portrait','appearance:93:person:harin':'navy hair'},negative:{},seeds:{},provider:'novelai',positiveBase:'user art style'}};};
test('full save file includes hired crew, image bytes, active version and fixed appearance',()=>{const f=fixture(),bundle=createBundle(f.state,f.images,f.settings),restored=decodeBundle(JSON.stringify(bundle));assert.equal(restored.state.crew.roster[0].id,'harin');assert.deepEqual(restored.images,f.images);assert.deepEqual(restored.settings,f.settings);f.images[0].active=null;assert.equal(bundle.images[0].active,id);});
test('invalid active images are rejected; old state-only saves are explicitly legacy',()=>{const f=fixture();f.images[0].active='missing';assert.throws(()=>createBundle(f.state,f.images,f.settings));f.images[0].active=id;f.images[0].versions[0].data='bad';assert.throws(()=>createBundle(f.state,f.images,f.settings));assert.equal(decodeBundle(JSON.stringify(f.state)).legacy,true);});
